practice(3,'Логическая модель данных','выделить сущности, атрибуты, ключи, отношения и правила кодирования.')
h('3.1 Сущности и связи')
p('Модель содержит 29 сущностей. Версия BOM хранит корпус и набор слотов. Слот выбирает ровно одно из двух описаний: конкретный компонент либо группу характеристик; закрепление точного SKU дополнительно ограничивает выбор поставщика. Разрешённый слот связывает его с конкретным предложением и фактическим компонентом. Снимки предложений и утверждённые версии не перезаписываются.')
p('Карточка имеет стабильный offer_id. Её версия ссылается на одну версию BOM, результат проверки и правило расчёта. Изображения связаны с версией карточки через таблицу связи. Публикация относится к конкретной версии карточки и хранит собственное состояние обработки. Поэтому новый расчёт или новая BOM не меняют историю уже отправленного содержимого.')
def logical_keys(tb):
 pk=[c['name'] for c in tb['columns'] if 'PRIMARY KEY' in c['rule']]
 pk += [v.replace('PRIMARY KEY ','') for v in tb['constraints'] if v.startswith('PRIMARY KEY')]
 refs=[c['name']+' → '+re.search(r'REFERENCES ([a-z_]+\([a-z_]+\))',c['rule']).group(1) for c in tb['columns'] if 'REFERENCES' in c['rule']]
 return 'PK: '+', '.join(pk)+('; FK: '+'; '.join(refs) if refs else '')
t('Сущности логической модели',['Сущность','Основные атрибуты','Ключи и отношения'],[[tb['title']+'\n'+tb['name'],', '.join(c['name'] for c in tb['columns']),logical_keys(tb)] for tb in tables],[3.8,7.3,5.4])
for i in range(1,6):draft('D03_logical_'+str(i),'Логическая модель данных Представление '+str(i))
t('Кардинальности основных связей',['Родитель','Дочерняя сущность','Кардинальность и ограничение'],[['supplier','supplier_product','1 : 0..N; SKU уникален внутри поставщика'],['supplier_product','supplier_offer','1 : 0..N; каждое предложение — снимок'],['bom','bom_version','1 : 1..N для созданной BOM; версия уникальна внутри BOM'],['bom_version','bom_slot','1 : 0..N в черновике; готовая версия имеет полный набор'],['bom_slot','slot_selection','1 : 0..1; выбранное предложение обязательно перед расчётом'],['component / component_group','bom_slot','0..1 : N для каждой альтернативы; выбран ровно один FK'],['card','card_version','1 : 1..N; номер версии уникален внутри карточки'],['card_version','publication','1 : 0..N; одновременно одна незавершённая операция'],['card_version ↔ image_asset','card_image','M:N; позиция изображения уникальна в версии'],['app_user ↔ role','user_role','M:N; сочетание пользователя и роли уникально']],[4.2,4.2,8.1])
