t('Кодификатор ролей',['Код','Роль','Назначение'],[['MANAGER','Менеджер маркетплейсов','Запросы, карточки, утверждение, публикация'],['ENGINEER','Технический специалист','BOM, совместимость и замены'],['STOCK','Сотрудник склада','Предложения и сопоставление'],['DESIGNER','Дизайнер','Шаблоны, изображения и контент'],['ADMIN','Администратор','Доступ, настройки, аудит']],[3,5,8.5])
t('Кодификатор статусов карточки',['Код','Значение','Условие'],[['DRAFT','Черновик','Данные ещё не готовы'],['REVIEW','На проверке','Выполняется проверка и подготовка'],['READY','Готова к публикации','Совместимость и полнота подтверждены'],['PUBLISHED','Опубликована','Получен окончательный успешный результат'],['STALE','Требует актуализации','Изменились состав, цены или правила'],['PUBLISH_ERROR','Ошибка публикации','Получена постоянная ошибка или исчерпан лимит']],[3,5,8.5])
t('Прочие кодификаторы',['Объект','Коды','Смысл'],[['Компонент','CASE, CPU, BOARD, RAM, GPU, SSD, PSU, COOLER','Корпус, процессор, плата, память, видеокарта, накопитель, блок питания, охлаждение'],['Представление характеристики','NUMBER, TEXT','Число с единицей измерения либо строковое значение'],['Версия BOM','DRAFT, CHECKED, ARCHIVED','Редактируемый черновик, проверенная версия, архив'],['Публикация','QUEUED, SENDING, WAITING, RETRY, SUCCESS, FAILED, UNCERTAIN','Очередь, отправка, ожидание, повтор, успех, отказ, неизвестный результат'],['Пакет замены','PREVIEW, RUNNING, DONE, PARTIAL, CANCELLED','Предпросмотр, выполнение, завершён, частичен, отменён'],['Результат замены BOM','PENDING, APPLIED, CONFLICT, SKIPPED','Ожидание, применено, конфликт, пропущено']],[3,6.5,7])
h('3.3 Правила кодирования')
draft('D04_coding','Схема формирования кода BOM',False)
t('Схема кодирования',['Код','Структура','Часть и значение','Диапазон и правило'],[['BOM','BOM-NNNNNN','BOM — тип; NNNNNN — порядковый номер','000001–999999; sequence без повторного использования'],['Компонент','CMP-NNNNNN','CMP — компонент; NNNNNN — номер','Общая последовательность, UNIQUE(code)'],['Карточка','UCOMS-NNNNNN','UCOMS — товарное предложение; номер','Стабильный offer_id на весь жизненный цикл'],['Версия','version_no','Положительный номер внутри объекта','1, 2, 3…; UNIQUE(parent_id, version_no)'],['Публикация','operation_key','Хеш идентичности версии карточки и операции','64 символа; UNIQUE; повтор сохраняет тот же ключ']],[2.8,4,4.8,4.9])
p('Бизнес-код не заменяет первичный ключ. Удалённые номера не переиспользуются, пропуски после отката транзакции допустимы. При исчерпании шестизначного диапазона требуется согласованное расширение формата. Создание кода выполняется сервером из sequence, а не через небезопасный конкурентный поиск MAX + 1. Обязательный уникальный индекс защищает от коллизий.')
h('3.4 Вывод')
p('Логическая модель покрывает исходные требования, включая групповые слоты, закреплённый SKU, историю предложений и массовые замены. Кодификаторы отделяют состояние карточки от состояния внешней операции, что исключает преждевременную отметку об успешной публикации.')

practice(4,'Интерфейсы и сценарии взаимодействия','подготовить каркасные экраны, подробные сценарии и диаграмму деятельности.')
h('4.1 Структура интерфейса')
p('Подготовлены шесть каркасных экранов. Главная навигация ведёт к карточкам, BOM, предложениям, заменам и публикациям. Доступность действия определяется ролью и состоянием объекта. Скрытая кнопка не заменяет серверную проверку. Все приведённые цены, количества и идентификаторы на макетах — демонстрационные значения.')
t('Экраны и пользовательские задачи',['Экран','Основные элементы','Сценарии и требования'],[['Список карточек','Поиск, фильтры, статус, ответственный','UC-01, UC-07; FR-01, FR-22'],['Редактор BOM','Версия, корпус, слоты, тип выбора, конфликты','UC-01, UC-02; FR-02–FR-05'],['Предложения','SKU, цена, остаток, дата, сопоставление','UC-03; FR-06–FR-08'],['Массовая замена','Правило, список BOM, конфликты, подтверждение','UC-04; FR-11–FR-13'],['Карточка','Цена, масса, атрибуты, изображения, проверка','UC-05, UC-06; FR-09, FR-10, FR-14–FR-17'],['Журнал публикаций','Очередь, статус, попытки, причины, уведомления','UC-06, UC-07; FR-18–FR-21']],[3.5,7,6])
for i,title in enumerate(['Список карточек','Редактор версии BOM','Предложения и сопоставления','Массовая замена','Карточка и публикация','Журнал публикаций и уведомления'],1):draft(f'D05_wireframe_{i:02d}','Каркас экрана '+title)
h('4.2 Подробные сценарии')
scenarios=[
('UC-01 Создание BOM','Менеджер и технический специалист','Пользователь авторизован; корпус есть в справочнике.','1. Менеджер создаёт запрос. 2. Инженер выбирает корпус. 3. Добавляет слоты с точной моделью или группой. 4. Сохраняет черновик. 5. Система присваивает код и версию, фиксирует аудит.','Нет корпуса — сохранить запрос без готовности. Не задано ни одно описание слота или заданы оба — показать ошибку у поля.','Новая версия DRAFT, существующие версии неизменны.'),
('UC-02 Проверка конфигурации','Инженер и ИС','Есть состав, характеристики и предложения.','1. Система разрешает группы. 2. Проверяет сокет, память, форм-фактор, питание и габариты. 3. Контролирует наличие и дату предложений. 4. Сохраняет протокол с версией правил.','Нет данных — проверка неуспешна с причиной, а не условный успех. Конфликт — показать правило и оба компонента, вернуть в редактор.','CHECKED только при отсутствии нарушений; иначе DRAFT.'),
('UC-03 Обновление предложений','Сотрудник склада, ИС и поставщик','Настроен адаптер и есть право запуска импорта.','1. Выбрать поставщика. 2. Загрузить данные. 3. Проверить схему, цену, количество и время. 4. Сохранить новые снимки. 5. Отметить затронутые карточки STALE.','Неизвестный SKU — очередь сопоставления. Недоступность — сохранить старые сведения и дату, назначить ограниченный повтор.','Обновлены только валидные предложения, показана сводка ошибок.'),
('UC-04 Массовая замена','Технический специалист','Заданы старый и новый компонент либо точные SKU.','1. Найти затронутые BOM. 2. Показать изменения цены, массы и конфликты. 3. Подтвердить допустимый набор. 4. Проверить неизменность исходных версий. 5. Создать и проверить новые версии в отдельных транзакциях.','Версия изменилась — CONFLICT и новый предпросмотр. Неуспешная проверка — откат этой BOM. Повтор пакета пропускает уже обработанные элементы.','Результат для каждой BOM; успешные карточки STALE. Автопубликации нет.'),
('UC-05 Подготовка контента','Менеджер, дизайнер и ИС','BOM проверена; все предложения актуальны.','1. Рассчитать цену и массу. 2. Сформировать название, описание и атрибуты. 3. Создать изображения из утверждённого шаблона. 4. Проверить полноту. 5. Сохранить версию карточки.','Отсутствует атрибут — показать поле и источник. Изображение не соответствует шаблону — вернуть дизайнеру. Изменились данные — повторить расчёт.','READY только для согласованного снимка.'),
('UC-06 Публикация карточки','Менеджер, фоновый worker и Ozon','Есть READY, право публикации и актуальная версия.','1. Менеджер утверждает версию. 2. Сервер фиксирует очередь и ключ операции. 3. Worker отправляет содержимое. 4. Сохраняет внешний ID. 5. Запрашивает окончательный результат. 6. Уведомляет ответственного.','Постоянная ошибка — FAILED. Тайм-аут — сверка результата; при допустимом временном отказе до трёх повторов. Устаревшая версия перед отправкой — отмена и новая проверка.','PUBLISHED только после подтверждения; иначе PUBLISH_ERROR с причиной.')]
for title,actors,pre,main,alt,post in scenarios:t(title,['Элемент','Описание'],[['Акторы',actors],['Предусловия',pre],['Основной поток',main],['Альтернативы',alt],['Постусловия',post]],[3.6,12.9])
